style.css:
@-moz-document domain("roblox.com") {
/* Apply your uploaded pink gradient as background */
    html, body {
        background: url("https://www.google.com/url?sa=i&url=https%3A%2F%2Fwww.pinterest.com%2Fpin%2F9570217952479924%2F&psig=AOvVaw1BSydK4FqFxOLK_8ZYnz33&ust=1758391866753000&source=images&cd=vfe&opi=89978449&ved=0CBYQjRxqFwoTCPDWpaq25Y8DFQAAAAAdAAAAABAf") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Foreground containers - make slightly transparent so background shows through */
    #container-main, 
    #content, 
    .container-main, 
    .content, 
    .rbx-body, 
    .rbx-main {
        background-color: rgba(255, 255, 255, 0.8) !important; /* soft white overlay */
        border-radius: 10px;
    }

    /* Text - keep readable */
    body, body * {
        color: #2a2a2a !important; /* dark grey text for contrast */
    }

    /* Headers / Navbars slightly pink */
    header, 
    .rbx-navbar, 
    .navbar, 
    footer, 
    .rbx-footer {
        background-color: rgba(255, 182, 193, 0.85) !important; /* light pink */
    }

    /* Optional hover effects */
    a:hover {
        color: #ff69b4 !important; /* hot pink hover */
    }
}
